# Part B · Section 10 — antiarrhythmic drugs (Scully) plus adenosine, digoxin and atropine
TBL = '<table style="border-collapse:collapse;margin:10px 0;font-size:14px"><tr>{}</tr></table>'
def hdr(*cols):
    return TBL.format(''.join(f'<th style="border:1px solid #bbb;padding:4px 10px;text-align:left">{c}</th>' for c in cols))

Q = [
dict(sec=10, img='B_class1', cap='Ventricular action potentials before (solid) and after (dashed) three sodium-channel-blocking drugs',
stem="An investigator records ventricular myocyte action potentials before and after three drugs that block fast sodium channels. The effects are shown; each drug slows the phase 0 upstroke to a different degree and has a different effect on repolarization.{FIG}Drug 1 is most likely which of the following?",
choices=["Flecainide","Lidocaine","Mexiletine","Procainamide","Sotalol","Verapamil"], key=3,
exp="All three are <b>class I</b> sodium-channel blockers, separated by how much they slow phase 0 (\"salty CAB driver\": C > A > B) and what they do to repolarization (Goldilocks):<br>• <b>Drug 1 — class IA</b> (quinidine, <b>procainamide</b>, disopyramide): moderate sodium block and <b>prolonged repolarization</b> (it also blocks potassium channels), so a longer QT and a torsades risk.<br>• Drug 2 — class IB (lidocaine, mexiletine): mild block, shortened repolarization.<br>• Drug 3 — class IC (flecainide, propafenone): marked block, no change in repolarization.<br><br><b>Educational objective:</b> Class IA drugs moderately slow phase 0 and prolong repolarization; IB mildly slow it and shorten repolarization; IC markedly slow it without changing repolarization.",
wrong={0:"Flecainide (class IC) causes the most marked upstroke slowing with no change in repolarization — drug 3.",
1:"Lidocaine (class IB) causes mild upstroke slowing and shortens repolarization — drug 2.",
2:"Mexiletine is the oral class IB drug, with lidocaine's profile — drug 2, not drug 1.",
4:"Sotalol blocks β receptors and potassium channels; it prolongs repolarization without slowing phase 0.",
5:"Verapamil blocks L-type calcium channels, acting on nodal tissue rather than the myocyte upstroke."},
eli5="All three slow the cell's sodium-driven upstroke. Drug 1 also keeps the cell from resetting quickly, which stretches the action potential out; that's the class IA group, like procainamide."),

dict(sec=10, img=None,
stem="A 66-year-old man has frequent premature ventricular beats and runs of nonsustained ventricular tachycardia 1 day after an acute myocardial infarction. Intravenous lidocaine suppresses the ectopy with little effect on the electrocardiogram of the normally perfused myocardium.{FIG}Which of the following best explains lidocaine's selectivity for ischemic tissue?",
choices=["It binds open or inactivated channels and unbinds fast","It blocks L-type calcium channels in depolarized cells","It hyperpolarizes cells by opening potassium channels","It is concentrated in ischemic tissue by low blood flow","It prolongs the action potential of healthy myocytes"], key=0,
exp="Class I drugs bind sodium channels in their <b>open and inactivated</b> states — <b>use-dependent block</b>: the faster a tissue fires, the more block builds up. Class IB drugs like lidocaine also <b>dissociate rapidly</b>, so in healthy tissue the block washes off between beats. <b>Ischemic tissue cannot hold its membrane potential</b>, fires more often and keeps its channels in the bindable states, so the block accumulates there. Hence the mnemonic \"IB is Best after a myocardial infarction.\"<br><br><b>Educational objective:</b> Lidocaine (class IB) is use-dependent and rapidly dissociating, so it preferentially blocks depolarized, rapidly firing ischemic tissue.",
wrong={1:"Lidocaine blocks sodium, not calcium, channels.",
2:"Lidocaine does not open potassium channels; that is adenosine's effect on nodal tissue.",
3:"Low blood flow would deliver less drug to ischemic tissue, not more; selectivity comes from channel-state binding.",
4:"Class IB drugs shorten, not prolong, the action potential."},
eli5="Lidocaine sticks to sodium channels only while they're busy and lets go fast. Injured heart muscle fires constantly, keeping its channels busy, so lidocaine collects there and leaves healthy muscle alone."),

dict(sec=10, img=None,
stem="A 64-year-old man with a myocardial infarction 3 years ago and a left ventricular ejection fraction of 35% has recurrent symptomatic atrial fibrillation. A rhythm-control drug is being chosen.{FIG}Which of the following drugs would most increase his risk of a fatal ventricular arrhythmia?",
choices=["Amiodarone","Digoxin","Dofetilide","Flecainide","Metoprolol"], key=3,
exp="<b>Class IC drugs (flecainide, propafenone) are contraindicated in structural or ischemic heart disease</b>: in scarred myocardium their marked use-dependent sodium block slows conduction enough to promote re-entrant ventricular arrhythmias. The CAST trial (board add-on) showed higher mortality with class IC drugs after myocardial infarction. The hook: \"IB is Best after a myocardial infarction (MI); IC is Contraindicated.\" Flecainide is for preventing atrial fibrillation in a <b>structurally normal heart</b>. Amiodarone and dofetilide are usable with a reduced ejection fraction.<br><br><b>Educational objective:</b> Avoid class IC drugs (flecainide, propafenone) after myocardial infarction or with structural heart disease (CAST).",
wrong={0:"Amiodarone has almost no negative inotropy and a low torsades risk, so it is usable with a reduced ejection fraction.",
1:"Digoxin is a rate-control option in heart failure; it is not contraindicated here.",
2:"Dofetilide has no negative inotropic effect and is usable with a reduced ejection fraction (started in hospital).",
4:"Metoprolol is a mortality-reducing drug after infarction and in heart failure with reduced ejection fraction."},
eli5="Flecainide slows conduction a lot, and in a heart with old scar that can set up deadly loops of electricity. So it's only for hearts that are structurally normal."),

dict(sec=10, img='B_flutter1to1', cap='12-lead electrocardiogram',
stem="A 42-year-old cyclist with known atrial flutter takes flecainide alone. He comes to the emergency department after he felt faint during a ride. His pulse is 250/min and regular. His electrocardiogram is shown; the machine reads it as ventricular tachycardia.{FIG}Which of the following measures would most likely have prevented this event?",
choices=["Adding an atrioventricular nodal blocker","Avoiding caffeine before every long ride","Increasing the daily dose of flecainide","Switching flecainide to intravenous lidocaine","Taking flecainide only when symptomatic"], key=0,
exp="A regular wide tachycardia at 250 in a patient with <b>flutter on a class IC drug</b> is <b>1:1 atrial flutter with use-dependent QRS widening</b>. Flecainide <b>slows the flutter circuit</b> (say from 300 to 250), slow enough for the atrioventricular node to conduct <b>every</b> flutter wave; at that fast rate, use-dependent sodium block widens the QRS further, so it mimics ventricular tachycardia. The giveaway is the history and a rapid initial QRS deflection. <b>Always give an atrioventricular nodal blocker alongside a class IC drug.</b><br><br><b>Educational objective:</b> Class IC drugs can slow atrial flutter enough to allow 1:1 conduction with a very fast, wide QRS; always combine them with an atrioventricular nodal blocker.",
wrong={1:"Caffeine is not the mechanism; the drug changed the flutter rate and the node's ability to keep up.",
2:"A higher flecainide dose would slow the flutter more and widen the QRS more, worsening the problem.",
3:"Lidocaine (class IB) has little atrial effect and is not a maintenance drug for flutter.",
4:"Intermittent dosing does not address the need for nodal blockade when the circuit is slowed."},
eli5="Flecainide slowed his flutter just enough that the heart's relay station could pass every single wave through. Adding a drug that slows the relay station stops that from happening."),

dict(sec=10, img=None,
stem="A 70-year-old man taking an oral antiarrhythmic for atrial fibrillation comes to the office because of ringing in his ears, blurred vision, headache and episodes of confusion. He also has diarrhea. His corrected QT interval is 510 ms.{FIG}Which of the following drugs is he most likely taking?",
choices=["Amiodarone","Dofetilide","Flecainide","Mexiletine","Procainamide","Quinidine"], key=5,
exp="Tinnitus, reduced hearing, blurred vision, headache and delirium are <b>cinchonism</b>, named after the cinchona bark from which <b>quinidine</b> comes. Quinidine is the class IA prototype: it blocks open sodium channels and potassium channels, slowing conduction and lengthening the effective refractory period — and the QT, so torsades is a risk. Diarrhea and anticholinergic effects are common. It is contraindicated with QT prolongation and in myasthenia gravis; hypokalemia reduces its efficacy and worsens QT prolongation.<br><br><b>Educational objective:</b> Quinidine causes cinchonism (tinnitus, blurred vision, headache, delirium), diarrhea and QT prolongation with torsades.",
wrong={0:"Amiodarone causes pulmonary fibrosis, thyroid and liver disease, corneal deposits and photosensitivity, not cinchonism.",
1:"Dofetilide prolongs the QT but does not cause tinnitus or delirium.",
2:"Flecainide causes blurred vision and dizziness but not cinchonism or diarrhea, and it does not prolong repolarization.",
3:"Mexiletine causes tremor, dizziness and nausea; it shortens rather than prolongs repolarization.",
4:"Procainamide shares quinidine's QT prolongation but causes drug-induced lupus, not cinchonism, and it is not derived from cinchona bark."},
eli5="Quinidine comes from the same tree bark as quinine, and too much causes ringing ears, blurry vision and confusion — a pattern called cinchonism."),

dict(sec=10, img=None,
stem="A 74-year-old woman takes digoxin for heart failure and atrial fibrillation, with a stable therapeutic serum concentration. An additional antiarrhythmic is to be added, and her physician wants to avoid raising her serum digoxin concentration.{FIG}Which of the following drugs can be added without raising her digoxin concentration?",
choices=["Amiodarone","Procainamide","Quinidine","Verapamil"], key=1,
exp="Several antiarrhythmics raise digoxin levels — a stated board favourite. <b>Quinidine</b> displaces digoxin from plasma protein binding (the free drug is the active drug, so displacing it is like giving a bigger dose) and <b>reduces its renal clearance</b>. <b>Verapamil</b> (and diltiazem) compete with digoxin for renal excretion. <b>Amiodarone</b> inhibits its clearance (P-glycoprotein and cytochrome P450 (CYP) effects). <b>Procainamide does not alter digoxin levels</b>, though it brings drug-induced lupus with chronic use and needs renal dosing (its metabolite N-acetylprocainamide (NAPA) is renally cleared).<br><br><b>Educational objective:</b> Quinidine, verapamil/diltiazem and amiodarone raise serum digoxin; procainamide does not.",
wrong={0:"Amiodarone reduces digoxin clearance and raises its level; the digoxin dose is usually reduced when amiodarone starts.",
2:"Quinidine displaces digoxin from protein binding and reduces its renal clearance, raising free digoxin.",
3:"Verapamil competes with digoxin for renal excretion, raising its level."},
eli5="Quinidine pushes digoxin off its carrier proteins and slows its removal by the kidneys, so digoxin levels climb. Procainamide doesn't do that."),

dict(sec=10, img='B_butterfly', cap='Facial photograph of this patient',
stem="A 58-year-old man has taken an oral antiarrhythmic for ventricular arrhythmias for 14 months. He now has a 1-month history of joint pains in both hands and the rash shown. Antinuclear antibody and antihistone antibody tests are positive; anti–double-stranded DNA antibodies are negative. The drug is metabolized by acetylation in the liver.{FIG}Which of the following drugs is most likely responsible?",
choices=["Amiodarone","Digoxin","Flecainide","Lidocaine","Procainamide"], key=4,
exp="A malar (butterfly) rash with arthralgias, positive antihistone antibodies and negative anti-double-stranded DNA after long-term therapy is <b>drug-induced lupus</b>. Among antiarrhythmics, <b>procainamide</b> is the classic cause, more often in <b>slow acetylators</b> (it is acetylated in the liver to N-acetylprocainamide, N-acetylprocainamide (NAPA), then cleared by the kidneys). Procainamide also prolongs the QT like quinidine and is the drug of choice for preexcited atrial fibrillation in Wolff–Parkinson–White. Stopping the drug resolves the lupus.<br><br><b>Educational objective:</b> Long-term procainamide causes drug-induced lupus (antihistone antibodies), especially in slow acetylators.",
wrong={0:"Amiodarone causes a blue-grey skin discoloration and photosensitivity, not a lupus syndrome.",
1:"Digoxin toxicity causes visual changes, nausea and arrhythmias, not lupus.",
2:"Flecainide causes dizziness, visual blurring and proarrhythmia, not lupus.",
3:"Lidocaine is given intravenously for short periods and causes central nervous system effects, not lupus."},
eli5="Some people clear procainamide slowly, and after months it can trigger a lupus-like reaction with a butterfly rash and sore joints. Stopping the drug makes it go away."),

dict(sec=10, img=None,
stem="A 76-year-old man with benign prostatic hyperplasia is started on an oral antiarrhythmic for ventricular ectopy. One week later he comes to the emergency department because he cannot pass urine; he also has a dry mouth and constipation.{FIG}Which of the following drugs is most likely responsible?",
choices=["Disopyramide","Dofetilide","Mexiletine","Propafenone","Sotalol"], key=0,
exp="Urinary retention, dry mouth and constipation are <b>anticholinergic</b> effects. Among antiarrhythmics, <b>disopyramide</b> (class IA) has the <b>most profound anticholinergic effects</b>, with fewer gastrointestinal effects than quinidine; it is also negatively inotropic and can worsen heart failure. In an older man with prostatic hyperplasia, it readily causes urinary retention.<br><br><b>Educational objective:</b> Disopyramide (class IA) has prominent anticholinergic effects (urinary retention, dry mouth, constipation) and negative inotropy.",
wrong={1:"Dofetilide's main risk is QT prolongation and torsades; it is not anticholinergic.",
2:"Mexiletine causes tremor, dizziness and nausea, not anticholinergic effects.",
3:"Propafenone causes a metallic taste, dizziness and some beta-blockade, not urinary retention.",
4:"Sotalol causes bradycardia, fatigue and torsades, not anticholinergic effects."},
eli5="Disopyramide blocks acetylcholine as a side effect, so the bladder can't squeeze well. In an older man with a big prostate, that means he can't pee."),

dict(sec=10, img=None,
stem="A 61-year-old man with alcoholic cirrhosis is admitted with ventricular tachycardia and started on an intravenous infusion of an antiarrhythmic at the standard dose. Twelve hours later he reports numbness around his mouth, becomes confused and has a generalized seizure.{FIG}Which of the following best explains these effects?",
choices=["Amiodarone-induced hypothyroidism","Central sodium-channel block by lidocaine","Cinchonism from quinidine","Hyperkalemia from digoxin","QT prolongation with torsades from sotalol"], key=1,
exp="<b>Lidocaine</b> is the intravenous class IB drug used as second-line therapy for ventricular arrhythmias. It is cleared by the <b>liver</b>, so in cirrhosis a standard dose accumulates. Because it also <b>blocks sodium channels in the central nervous system</b> (it is a local anesthetic), toxicity causes perioral numbness, confusion, dizziness, tremor and <b>seizures</b>; methemoglobinemia can also occur. Adjust the dose for hepatic function.<br><br><b>Educational objective:</b> Lidocaine toxicity — perioral numbness, confusion and seizures from central sodium-channel blockade — occurs with hepatic dysfunction unless the dose is reduced.",
wrong={0:"Hypothyroidism develops over months of amiodarone and does not cause seizures within hours.",
2:"Quinidine is oral and causes tinnitus and blurred vision; it is not given as an infusion for ventricular tachycardia here.",
3:"Digoxin toxicity causes nausea, yellow vision and arrhythmias, and he was not given digoxin.",
4:"Torsades would cause syncope from an arrhythmia, not perioral numbness preceding a seizure."},
eli5="Lidocaine is broken down by the liver, and his liver is damaged, so the drug built up. Too much lidocaine numbs nerves in the brain too, causing confusion and seizures."),

dict(sec=10, img=None,
stem="A 24-year-old woman with congenital long QT syndrome (corrected QT 500 ms) is to start a beta-blocker to reduce her risk of arrhythmic events.{FIG}Which of the following beta-blockers would most increase her risk of torsades de pointes?",
choices=["Atenolol","Metoprolol","Nadolol","Propranolol","Sotalol"], key=4,
exp="Beta-blockers reduce sympathetically triggered torsades in long QT syndrome. <b>Sotalol</b>, however, is a <b>mixed class II and III</b> drug: besides blocking β receptors it <b>blocks repolarizing potassium channels</b>, prolonging phases 2 and 3 and the QT — and it causes torsades. Dr. Scully's \"nitty-gritty\" answer for a patient with a prolonged QT is <b>propranolol</b>, because it does not prolong repolarization (nadolol is also commonly used).<br><br><b>Educational objective:</b> Sotalol prolongs the QT (class III action) and is contraindicated in long QT; propranolol does not prolong repolarization.",
wrong={0:"Atenolol is a β1-selective blocker without potassium-channel effects; it does not prolong the QT.",
1:"Metoprolol is a β1-selective blocker without class III effects.",
2:"Nadolol is a nonselective blocker frequently used in congenital long QT syndrome.",
3:"Propranolol does not prolong repolarization and is the lecture's answer for a long QT."},
eli5="Sotalol is a beta-blocker that also slows the heart's reset, which stretches the QT even more. In someone whose QT is already long, that's dangerous."),

dict(sec=10, img=None,
stem="A 29-year-old woman at 30 weeks' gestation has a blood pressure of 162/104 mm Hg on repeated measurements. Labetalol is started.{FIG}Which property of labetalol makes it preferable to a pure β1-selective blocker in pregnancy?",
choices=["α1 blockade preventing placental vasoconstriction","β2 agonist action that relaxes the uterus","Central α2 agonism lowers sympathetic outflow","Inhibition of nitric oxide synthase in the placenta","Inability to cross the placenta into the fetus"], key=0,
exp="Lowering cardiac output with a beta-blocker alone would trigger the <b>baroreceptor reflex</b>, clamping down peripheral vessels — <b>including those perfusing the placenta</b>. <b>Labetalol</b> is a third-generation beta-blocker that also <b>blocks α1 receptors</b>, preventing that compensatory vasoconstriction, so placental perfusion is protected. That is when a beta-blocker is first-line for hypertension: in pregnancy, and the answer is labetalol.<br><br><b>Educational objective:</b> Labetalol (β + α1 blockade) is first-line for hypertension in pregnancy because its α1 blockade prevents reflex vasoconstriction that would reduce placental perfusion.",
wrong={1:"Labetalol is not a β2 agonist (terbutaline is, used as a tocolytic).",
2:"Central α2 agonism is methyldopa's mechanism, another pregnancy option.",
3:"Labetalol does not inhibit nitric oxide synthase; that would constrict placental vessels.",
4:"Labetalol does cross the placenta; its advantage is hemodynamic."},
eli5="A plain beta-blocker lowers the heart's output, and the body responds by squeezing blood vessels, including the placenta's. Labetalol also blocks that squeeze, so the baby keeps its blood supply."),

dict(sec=10, img=None,
stem="A 70-year-old woman in the intensive care unit after cardiac surgery develops atrial fibrillation with a rapid ventricular response. Her blood pressure is labile, and the team wants a beta-blocker whose effect can be stopped within minutes if she becomes hypotensive.{FIG}Which of the following drugs is most appropriate?",
choices=["Atenolol","Carvedilol","Esmolol","Nadolol","Propranolol"], key=2,
exp="<b>Esmolol</b> is a β1-selective blocker with a <b>very short half-life</b> (minutes; hydrolyzed by red-cell esterases): it \"washes in and washes out,\" which suits a <b>hemodynamically unstable</b> patient because the infusion can be titrated and stopped quickly. In practice it is limited by the volume of fluid needed to run it. The others act for hours.<br><br><b>Educational objective:</b> Esmolol, an ultrashort-acting IV β1 blocker, is used when rapid titration or quick reversal is needed in unstable patients.",
wrong={0:"Atenolol is long-acting and renally cleared; its effect cannot be switched off quickly.",
1:"Carvedilol is oral and long-acting, and its α1 blockade adds hypotension.",
3:"Nadolol has a very long half-life.",
4:"Propranolol's effect lasts hours and it is nonselective."},
eli5="Esmolol wears off in minutes, so if her blood pressure drops you can turn it off and the effect disappears almost right away."),

dict(sec=10, img=None,
stem="A 27-year-old man with asthma is given oral propranolol for recurrent supraventricular tachycardia. Two days later he comes to the emergency department with severe wheezing that responds poorly to albuterol.{FIG}Blockade of which of the following receptors best explains his symptoms?",
choices=["α1-Adrenergic","α2-Adrenergic","β1-Adrenergic","β2-Adrenergic","M3 muscarinic"], key=3,
exp="<b>Propranolol</b> is a first-generation, <b>nonselective</b> beta-blocker (β1 and β2). Bronchial smooth muscle relaxes through <b>β2</b> receptors (Gs → cyclic adenosine monophosphate (cAMP)), and albuterol works by stimulating them. Blocking β2 causes <b>bronchospasm</b> and blunts the response to albuterol. Nonselective blockers are not for asthmatics; a β1-selective blocker (metoprolol, atenolol) carries less risk, though caution remains. β2 blockade also causes vasospasm, cold extremities and impotence.<br><br><b>Educational objective:</b> Nonselective beta-blockers (propranolol) block bronchial β2 receptors, causing bronchospasm and blunting β2-agonist rescue in asthma.",
wrong={0:"α1 receptors constrict vascular smooth muscle; propranolol does not block them.",
1:"α2 receptors are presynaptic and central; they do not control airway tone.",
2:"β1 blockade slows the heart and lowers renin; it does not constrict the airways.",
4:"M3 receptor blockade relaxes the airways (ipratropium); activation, not blockade, would cause bronchospasm."},
eli5="Airways open up through β2 receptors, which is how his inhaler works. Propranolol blocks β2 as well as β1, so his airways tighten and the inhaler can't get through."),

dict(sec=10, img=None,
stem="A 63-year-old man with type 1 diabetes mellitus takes insulin and recently started propranolol. He is brought to the emergency department after he was found confused; his capillary glucose is 38 mg/dL. His wife says he had none of the shakiness or racing heart he usually feels when his sugar is low.{FIG}Which of the following best explains the absence of warning symptoms?",
choices=["β blockade masking the adrenergic warning signs","Insulin resistance caused by β blockade","Propranolol-induced hyperglycemia rebound","Reduced cerebral glucose uptake caused by propranolol","Stimulation of glucagon release by propranolol"], key=0,
exp="The early warning symptoms of hypoglycemia — <b>tremor, palpitations, tachycardia, anxiety</b> — come from the <b>sympathetic (adrenergic) response</b>. Beta-blockers <b>blunt those signs</b> (sweating, which is cholinergic, is preserved), so a diabetic patient on insulin may not notice a low glucose until neuroglycopenic symptoms such as confusion appear. Nonselective blockers also impair glycogenolysis, slowing recovery. Other cautions: taper beta-blockers (abrupt withdrawal causes rebound tachycardia and acute coronary syndrome), and avoid them before α blockade in pheochromocytoma or cocaine use (unopposed α stimulation).<br><br><b>Educational objective:</b> Beta-blockers mask the adrenergic warning signs of hypoglycemia (tremor, palpitations, tachycardia) in diabetic patients.",
wrong={1:"Beta-blockers do not cause the profound hypoglycemia here through insulin resistance, which would raise glucose.",
2:"Rebound hyperglycemia is not a beta-blocker effect and would not explain missing symptoms.",
3:"Propranolol does not reduce brain glucose uptake.",
4:"Glucagon release is not stimulated by propranolol; β blockade impairs counter-regulation."},
eli5="The shaky, racing-heart feeling of low blood sugar comes from adrenaline, and propranolol blocks adrenaline's effects. So his body's alarm was muted until his brain ran short of sugar."),

dict(sec=10, img=None,
stem="A 70-year-old man with heart failure and a left ventricular ejection fraction of 25% has symptomatic persistent atrial fibrillation. Rhythm control is planned with an oral drug that has no negative inotropic effect and is renally excreted. Because of a 1–3% risk of torsades de pointes, it must be started in hospital with QT monitoring and dosed by creatinine clearance.{FIG}Which of the following drugs is being described?",
choices=["Disopyramide","Dofetilide","Flecainide","Propafenone","Verapamil"], key=1,
exp="<b>Dofetilide</b> is an oral <b>class III</b> drug that inhibits the rapid delayed-rectifier potassium current, lengthening phases 2 and 3 and the effective refractory period. It is used for <b>conversion of atrial fibrillation and flutter and maintenance of sinus rhythm</b>. It has <b>no negative inotropy</b>, so it is usable with a <b>depressed ejection fraction</b>; it is <b>renally excreted</b> (dose by creatinine clearance) and causes torsades in about 1–3%, so it is started in hospital — not an outpatient start.<br><br><b>Educational objective:</b> Dofetilide (class III) maintains sinus rhythm, is usable with reduced ejection fraction, is dosed by renal function, and is started in hospital because of torsades risk.",
wrong={0:"Disopyramide is negatively inotropic and can worsen heart failure.",
2:"Flecainide (class IC) is contraindicated in structural heart disease and reduced ejection fraction.",
3:"Propafenone (class IC) is contraindicated in structural heart disease.",
4:"Verapamil is a negative inotrope used for rate, not rhythm, control and is avoided in reduced ejection fraction."},
eli5="Dofetilide holds the heart in normal rhythm without weakening the squeeze, so it's okay in heart failure. But it can stretch the QT dangerously, so it's always started in the hospital."),

dict(sec=10, img=None,
stem="A 59-year-old man presents with atrial flutter that began 6 hours ago. He is hemodynamically stable and has been in sinus rhythm before. The team prefers chemical rather than electrical cardioversion and chooses an intravenous class III drug that inhibits the delayed-rectifier potassium current and enhances the slow inward sodium current. He is monitored for 4 hours after the infusion.{FIG}Which of the following drugs was given?",
choices=["Amiodarone","Dofetilide","Ibutilide","Procainamide","Sotalol"], key=2,
exp="<b>Ibutilide</b> is an <b>intravenous</b> class III drug that <b>inhibits the delayed-rectifier potassium current and enhances the slow inward sodium current</b>. It is used to <b>terminate</b> atrial fibrillation and flutter — chemical cardioversion, the alternative to electrical cardioversion — and it only terminates; it does not maintain sinus rhythm. Torsades occurs in about 2%, so patients are monitored after the infusion. Dofetilide, by contrast, is oral and also maintains sinus rhythm.<br><br><b>Educational objective:</b> Ibutilide is an intravenous class III drug for acute chemical termination of atrial fibrillation and flutter, with about a 2% torsades risk.",
wrong={0:"Amiodarone has class I–IV actions, is slow to convert atrial flutter and is not defined by enhancing the slow sodium current.",
1:"Dofetilide is oral and used for conversion and maintenance; it does not enhance the slow sodium current.",
3:"Procainamide is a class IA sodium-channel blocker, not a class III drug.",
4:"Sotalol combines beta-blockade with potassium-channel block and is oral; it is not used for acute chemical conversion."},
eli5="Ibutilide is an intravenous drug that can snap atrial flutter or fibrillation back to normal rhythm. It only resets the rhythm; it doesn't keep it there."),

dict(sec=10, img=None,
stem="An investigator studies a drug in isolated cardiac tissue." + hdr('Sinoatrial nodal phase 4 slope','Ventricular action potential duration') + "{FIG}Which of the following sets of effects is most consistent with sotalol?",
choices=["Flatter, prolonged","Flatter, shortened","Flatter, unchanged","Steeper, prolonged","Unchanged, prolonged"], key=0,
exp="<b>Sotalol is a mixed class II and III drug.</b> Its <b>β blockade</b> removes sympathetic drive to the pacemaker, giving a <b>flatter phase 4</b> in the sinoatrial node (slower rate). Its <b>potassium-channel block</b> lengthens phases 2 and 3 in the myocyte, <b>prolonging the action potential</b> and the QT. \"Can you draw it? A flatter phase 4 in the node plus a longer plateau in the myocyte.\" Adverse effects of both classes: fatigue and bradycardia from class II, torsades from class III. It is used for severe ventricular arrhythmias (especially when amiodarone is not tolerated) and to prevent recurrent atrial fibrillation or flutter.<br><br><b>Educational objective:</b> Sotalol (class II + III) flattens nodal phase 4 and prolongs the myocyte action potential.",
wrong={1:"A flatter phase 4 with a shortened action potential fits a beta-blocker plus a class IB effect, not sotalol.",
2:"A flatter phase 4 with an unchanged action potential is a pure beta-blocker (class II), missing sotalol's class III action.",
3:"A steeper phase 4 is sympathetic stimulation, the opposite of β blockade.",
4:"An unchanged phase 4 with a prolonged action potential is a pure class III drug such as dofetilide."},
eli5="Sotalol does two jobs: as a beta-blocker it slows the pacemaker's drift, and as a potassium blocker it stretches out the muscle cell's reset."),

dict(sec=10, img='B_amioLung', cap='Chest radiograph of this patient',
stem="A 71-year-old man has taken an oral antiarrhythmic for 3 years for recurrent ventricular tachycardia. He comes to the office because of 2 months of dry cough and progressive shortness of breath. He has no fever. His chest radiograph is shown. His thyroid-stimulating hormone is elevated.{FIG}Which monitoring should have been in place for this drug?",
choices=["Lung, thyroid and liver function testing","Monthly antinuclear antibody titers","Serum drug levels and creatinine clearance only","Twice-weekly complete blood counts","Weekly serum potassium measurement only"], key=0,
exp="Interstitial lung disease and hypothyroidism after years of an antiarrhythmic for ventricular tachycardia point to <b>amiodarone</b>, which \"does all the things\" (class I–IV activity). Its organ toxicities need <b>long-term use</b>: <b>pulmonary fibrosis — the toxicity that kills</b> (baseline and annual pulmonary function tests), <b>hypo- or hyperthyroidism</b> (it is about 37% iodine; baseline and annual thyroid tests), <b>hepatotoxicity</b> (liver tests), corneal microdeposits (eye examinations), photosensitivity with blue-grey skin, and peripheral neuropathy. It also inhibits cytochrome P450 (CYP450), raising warfarin, digoxin and simvastatin levels.<br><br><b>Educational objective:</b> Amiodarone requires baseline and periodic pulmonary function, thyroid and liver tests (plus eye examinations); pulmonary fibrosis is its most dangerous toxicity.",
wrong={1:"Antinuclear antibody monitoring is relevant to procainamide (drug-induced lupus), not amiodarone.",
2:"Amiodarone is hepatically metabolized with a very long half-life; creatinine clearance dosing applies to dofetilide.",
3:"Blood counts are not the key amiodarone monitoring; its toxicities are lung, thyroid, liver and eye.",
4:"Potassium matters for many antiarrhythmics, but potassium alone would miss lung, thyroid and liver toxicity."},
eli5="This drug, amiodarone, can scar the lungs and upset the thyroid and liver over time. That's why patients need lung, thyroid and liver tests before starting and every year."),

dict(sec=10, img='B_cornea', cap='Slit-lamp photograph of the cornea',
stem="A 66-year-old woman taking a long-term antiarrhythmic for paroxysmal atrial fibrillation has a routine eye examination. She has no visual symptoms. A slit-lamp photograph of her cornea is shown. She has also noticed that she burns easily in the sun.{FIG}Which of the following drugs is she most likely taking?",
choices=["Amiodarone","Digoxin","Dofetilide","Flecainide","Sotalol"], key=0,
exp="<b>Corneal microdeposits</b> (a whorl-like keratopathy) are found in nearly all patients on long-term <b>amiodarone</b>; they are <b>usually harmless</b> and often discovered at a routine eye examination, which is why regular eye examinations are part of its monitoring. <b>Photosensitivity</b> and a blue-grey skin discoloration are its skin effects. Amiodarone is lipophilic with a half-life of weeks, so effects persist long after it is stopped.<br><br><b>Educational objective:</b> Amiodarone causes usually harmless corneal microdeposits and photosensitivity (blue-grey skin discoloration) with long-term use.",
wrong={1:"Digoxin toxicity causes yellow-green halos and altered color vision, not corneal deposits.",
2:"Dofetilide's main risk is QT prolongation; it does not deposit in the cornea.",
3:"Flecainide causes blurred vision as a central effect, without corneal deposits.",
4:"Sotalol causes bradycardia and torsades, not corneal deposits."},
eli5="Amiodarone builds up in tissues, including the clear front of the eye, leaving tiny golden specks that usually don't affect vision. It also makes the skin sensitive to the sun."),

dict(sec=10, img=None,
stem="A 72-year-old man takes warfarin with a stable INR of 2.4. Amiodarone is started for recurrent ventricular tachycardia. Three weeks later he has gum bleeding and his INR is 5.1. He has not changed his diet or other medications.{FIG}Which of the following best explains the change in his INR?",
choices=["Amiodarone displaces warfarin from albumin binding sites","Amiodarone-induced hyperthyroidism speeding vitamin K clearance","Amiodarone inhibits cytochrome P450 metabolism of warfarin","Amiodarone inhibits vitamin K epoxide reductase directly","Amiodarone reduces dietary vitamin K absorption"], key=2,
exp="<b>Amiodarone inhibits cytochrome P450 enzymes</b> (including cytochrome P450 2C9 (CYP2C9), which metabolizes S-warfarin, and cytochrome P450 3A4 (CYP3A4)), so warfarin accumulates and the INR rises — usually over weeks because of amiodarone's long half-life. The warfarin dose is typically reduced by a third to a half when amiodarone starts. It similarly raises digoxin and simvastatin levels.<br><br><b>Educational objective:</b> Amiodarone inhibits cytochrome P450 enzymes, raising warfarin (INR), digoxin and simvastatin levels.",
wrong={0:"Amiodarone raises the INR mainly by inhibiting warfarin metabolism, not by displacing it from albumin.",
1:"Thyrotoxicosis can increase warfarin sensitivity, but there is no evidence of it here, and the main mechanism is enzyme inhibition.",
3:"Amiodarone does not act directly on vitamin K epoxide reductase; that is warfarin's own target.",
4:"Amiodarone does not reduce vitamin K absorption."},
eli5="Amiodarone slows down the liver enzymes that break down warfarin, so warfarin builds up and the blood gets too thin."),

dict(sec=10, img=None,
stem="A 68-year-old man taking metoprolol for coronary disease develops a regular narrow-complex tachycardia at 170/min. Intravenous verapamil is given in the emergency department. Minutes later his blood pressure falls to 58/30 mm Hg; the monitor shows organized electrical complexes at 40/min, but no pulse can be felt.{FIG}Which of the following best explains this outcome?",
choices=["Additive negative inotropy and nodal block","Anaphylaxis to verapamil","Preexcited atrial fibrillation provoked by verapamil","Torsades de pointes from QT prolongation","Vasovagal reaction to the tachycardia"], key=0,
exp="<b>Intravenous verapamil plus a beta-blocker is contraindicated.</b> Both are negative inotropes and slow the nodes; together they can cause profound bradycardia, heart block and <b>irreversible electromechanical dissociation</b> — drug-induced heart failure with electrical activity but no effective contraction (pulseless electrical activity). The non-dihydropyridines also raise digoxin levels by competing for its renal excretion.<br><br><b>Educational objective:</b> intravenous verapamil (or diltiazem) combined with a beta-blocker can cause severe bradycardia and electromechanical dissociation; the combination is contraindicated.",
wrong={1:"Anaphylaxis would cause urticaria, angioedema or bronchospasm, not slow organized complexes without a pulse.",
2:"His rhythm was regular and narrow, without preexcitation, and the result is bradycardia, not a fast irregular rhythm.",
3:"Torsades is a fast polymorphic rhythm, not slow organized complexes.",
4:"A vasovagal reaction does not produce pulseless electrical activity after a drug."},
eli5="Metoprolol and verapamil both weaken and slow the heart. Given together, the heart's electrical signal keeps going but the muscle stops squeezing."),

dict(sec=10, img=None,
stem="A 77-year-old woman with heart failure and atrial fibrillation has taken digoxin at a stable dose with therapeutic levels for 2 years. Verapamil is added for better rate control. Two weeks later she has nausea, anorexia and blurred yellow vision, and her serum digoxin concentration has nearly doubled.{FIG}Which of the following best explains the rise in digoxin concentration?",
choices=["Decreased renal excretion of digoxin","Displacement of digoxin from plasma proteins","Increased intestinal absorption of digoxin","Inhibition of hepatic digoxin metabolism","Verapamil-induced hyperkalemia"], key=0,
exp="The non-dihydropyridine calcium channel blockers (verapamil, diltiazem) <b>compete with digoxin for renal excretion</b>, so digoxin accumulates. They also add pharmacodynamic nodal slowing and negative inotropy. Digoxin interactions are a board favourite:<br>• Pharmacokinetic: verapamil/diltiazem (renal excretion), quinidine (protein displacement plus reduced renal clearance), erythromycin and other oral antibiotics (kill gut bacteria that inactivate digoxin, so more is absorbed).<br>• Pharmacodynamic: potassium-wasting diuretics (hypokalemia increases digoxin binding), beta-blockers and calcium channel blockers (additive nodal slowing).<br><br><b>Educational objective:</b> Verapamil and diltiazem raise digoxin levels by reducing its renal excretion.",
wrong={1:"Protein-binding displacement is quinidine's mechanism, not verapamil's.",
2:"Increased absorption is the mechanism of erythromycin and other oral antibiotics, which kill digoxin-inactivating gut bacteria.",
3:"Digoxin is mainly excreted unchanged by the kidneys, so hepatic metabolism is minor.",
4:"Hyperkalemia would reduce digoxin's effect, not raise its concentration."},
eli5="Verapamil and digoxin share the same exit door in the kidneys, so verapamil slows digoxin's removal and it builds up."),

dict(sec=10, img=None,
stem="A 24-year-old hockey player collapses on the bench with a regular narrow-complex tachycardia at 192/min without visible P waves. A drug is pushed rapidly through an intravenous line followed by a saline flush. The rhythm stops after a brief pause, and the team notes that the bag-valve mask has become noticeably harder to squeeze.{FIG}By which of the following mechanisms did the drug terminate the arrhythmia?",
choices=["Blocking fast sodium channels in ventricular myocytes","Blocking L-type calcium channels in the nodal tissue","Inhibiting the sodium–potassium ATPase and raising vagal tone","Activating Gi-coupled receptors that open potassium channels","Stimulating muscarinic receptors on the sinoatrial node"], key=3,
exp="A rapid push with a flush that stops a narrow re-entrant tachycardia after a brief pause, followed by <b>bronchoconstriction</b> (the stiff bag — the clue in Dr. Scully's case), is <b>adenosine</b>. It binds the <b>P1 purinergic (A1) receptor</b>, a <b>Gi/o-coupled</b> receptor; the βγ subunit <b>opens potassium channels</b>, <b>hyperpolarizing</b> sinoatrial, atrial and atrioventricular nodal cells (and lowering cyclic adenosine monophosphate (cAMP)). The resulting transient atrioventricular block breaks circuits that use the node. Half-life under 10 seconds; bronchoconstriction can last up to 30 minutes in asthma.<br><br><b>Educational objective:</b> Adenosine acts on Gi-coupled P1 (A1) receptors, opening potassium channels and hyperpolarizing nodal tissue to produce transient atrioventricular block; it can cause bronchospasm.",
wrong={0:"Fast sodium-channel block is class I, which acts on myocytes and does not cause bronchospasm.",
1:"L-type calcium-channel block is verapamil and diltiazem, which act over minutes rather than seconds.",
2:"Na⁺/K⁺-ATPase inhibition with vagal effects is digoxin, which acts slowly.",
4:"Muscarinic stimulation is the vagal mechanism; adenosine works through its own purinergic receptor."},
eli5="Adenosine flips on a receptor that opens potassium doors in the heart's relay station, briefly shutting it down and breaking the loop. It can also tighten the airways for a while."),

dict(sec=10, img=None,
stem="A 66-year-old man with chronic obstructive pulmonary disease who takes theophylline daily has a stable regular narrow-complex tachycardia at 176/min. He drank three cups of coffee this morning. Adenosine 6 mg and then 12 mg by rapid push with a flush have no effect on the rhythm or the heart rate.{FIG}Which of the following best explains the lack of response?",
choices=["Adenosine was metabolized before reaching the heart","His rhythm is atrial fibrillation","Methylxanthines block adenosine receptors","Theophylline induces adenosine-degrading enzymes","Theophylline opens nodal potassium channels"], key=2,
exp="<b>Theophylline and caffeine are methylxanthines that competitively block adenosine receptors</b>, so larger doses are needed, or adenosine may fail. Here neither dose slowed the rate even transiently, which points to receptor blockade rather than a rhythm that does not involve the node (in flutter, adenosine still produces transient block that unmasks flutter waves). Dipyridamole does the opposite: it blocks adenosine reuptake and potentiates it. Next steps: a nodal blocker (beta-blocker caution in lung disease; diltiazem or verapamil) or cardioversion.<br><br><b>Educational objective:</b> Theophylline and caffeine antagonize adenosine receptors, so adenosine may need larger doses or fail; dipyridamole potentiates it.",
wrong={0:"A correctly given rapid push with a flush reaches the heart; both doses were given properly.",
1:"Atrial fibrillation is irregular; his tachycardia is regular.",
3:"Theophylline does not induce adenosine-degrading enzymes; it blocks the receptors.",
4:"Theophylline does not open potassium channels; adenosine's own effect is to open them."},
eli5="Caffeine and theophylline sit in adenosine's receptors and block it from working. So the usual doses of adenosine don't do anything."),

dict(sec=10, img=None,
stem="An investigator studies the inotropic effect of digoxin in isolated ventricular myocytes.{FIG}Which of the following sequences best explains how digoxin increases contractility?",
choices=["Blocks Na⁺/K⁺-ATPase → ↑ cell Na⁺ → ↓ Ca²⁺ efflux → ↑ stored Ca²⁺","Blocks Na⁺/K⁺-ATPase → ↓ intracellular Na⁺ → ↑ Ca²⁺ extrusion → ↑ Ca²⁺ sensitivity","Opens L-type Ca²⁺ channels → ↑ Ca²⁺ entry → ↑ calcium-induced Ca²⁺ release","Stimulates β1 receptors → ↑ cAMP → ↑ phospholamban phosphorylation","Inhibits phosphodiesterase 3 → ↑ cAMP → ↑ L-type Ca²⁺ current"], key=0,
exp="<b>Digoxin blocks the sarcolemmal Na⁺/K⁺-ATPase</b> → intracellular sodium rises → the <b>sodium–calcium exchanger</b> (which uses the sodium gradient to push calcium out) can no longer extrude calcium as well, and may run backwards → more calcium is pumped into the <b>sarcoplasmic reticulum</b> → bigger calcium-induced calcium release → stronger contraction. Separately, digoxin increases vagal tone and slows atrioventricular nodal conduction, which is why it is used for rate control in atrial fibrillation.<br><br><b>Educational objective:</b> Digoxin inhibits Na⁺/K⁺-ATPase, raising intracellular sodium, reducing calcium extrusion via the Na⁺/Ca²⁺ exchanger and enlarging sarcoplasmic reticulum (SR) calcium stores, which increases contractility.",
wrong={1:"Blocking the pump raises, not lowers, intracellular sodium, and that reduces calcium extrusion.",
2:"Digoxin does not open L-type channels directly.",
3:"β1 stimulation through cAMP is the mechanism of dobutamine.",
4:"Phosphodiesterase-3 inhibition is the mechanism of milrinone and inamrinone."},
eli5="Digoxin jams the cell's sodium pump, so sodium builds up inside. With less sodium gradient, the cell can't push calcium out as well, so more calcium is stored and released, and the heart squeezes harder."),

dict(sec=10, img=None,
stem="An 81-year-old woman taking digoxin for atrial fibrillation is started on furosemide for leg edema. One week later she has nausea, anorexia and sees yellow halos around lights. Her pulse is 52/min. The serum digoxin concentration is at the upper end of the therapeutic range.{FIG}Which of the following laboratory values should be checked first?",
choices=["Serum calcium","Serum magnesium","Serum potassium","Serum sodium","Thyroid-stimulating hormone"], key=2,
exp="<b>Potassium is the key to everything about digoxin.</b> The loop diuretic has likely caused <b>hypokalemia</b>. Potassium and digoxin compete for the Na⁺/K⁺-ATPase; low extracellular potassium increases digoxin binding (and the pump's affinity for it), producing toxicity even at a \"therapeutic\" level. Dr. Scully: we do not need an antidote if all we have to do is fix the potassium. Toxicity: nausea, anorexia, yellow-green halos (xanthopsia), confusion, bradycardia and arrhythmias. (Magnesium also matters, but potassium is checked first.)<br><br><b>Educational objective:</b> In suspected digoxin toxicity, check potassium first: hypokalemia (e.g., from loop or thiazide diuretics) increases digoxin binding and toxicity.",
wrong={0:"Hypercalcemia can potentiate digoxin, but furosemide lowers potassium, the classic precipitant.",
1:"Low magnesium also worsens toxicity, but potassium is the first and most important value to check.",
3:"Sodium does not directly change digoxin binding.",
4:"Thyroid status affects digoxin requirements over time, but it is not the first test after starting a diuretic."},
eli5="Digoxin and potassium compete for the same spot on the sodium pump. When the water pill drops her potassium, digoxin grabs more spots and becomes toxic, so check potassium first."),

dict(sec=10, img='B_dig', cap='12-lead electrocardiogram',
stem="A 64-year-old woman with heart failure and atrial fibrillation has a routine electrocardiogram, shown below. She has no chest pain, and troponin is normal.{FIG}Which of the following medications is she most likely taking?",
choices=["Amiodarone","Digoxin","Dofetilide","Flecainide","Quinidine"], key=1,
exp="Down-sloping, scooped ST depression — the \"<b>reverse check</b>\" or reverse tick — with a <b>shortened QT</b> is the <b>digitalis effect</b>: \"Here is the tracing — what drug are they on?\" is a common question. It indicates digoxin exposure, not necessarily toxicity. Toxicity adds arrhythmias: premature ventricular beats, bigeminy, bidirectional ventricular tachycardia, atrial tachycardia with block.<br><br><b>Educational objective:</b> Scooped (reverse-check) ST depression with a short QT is the digitalis effect.",
wrong={0:"Amiodarone prolongs the QT and can cause bradycardia, not scooped ST depression with a short QT.",
2:"Dofetilide prolongs the QT.",
3:"Flecainide widens the QRS and PR without scooping the ST segment.",
4:"Quinidine prolongs the QT and QRS rather than shortening the QT."},
eli5="Digoxin gives the ST segment a scooped, hockey-stick shape and shortens the QT. Spotting that shape tells you the patient is on digoxin."),

dict(sec=10, img=None,
stem="A 19-year-old woman is brought to the emergency department 3 hours after swallowing her grandmother's entire bottle of digoxin. She is vomiting. Her pulse is 44/min with intermittent atrioventricular block. Serum potassium concentration is 6.4 mEq/L.{FIG}Which of the following is the most appropriate treatment?",
choices=["Calcium gluconate as the definitive antidote","Digoxin immune antibody fragments","Intravenous potassium chloride","Quinidine to stabilize the rhythm","Sodium polystyrene sulfonate alone"], key=1,
exp="An <b>acute digoxin overdose causes hyperkalemia</b>, because the Na⁺/K⁺-ATPase pumps throughout the body are blocked and potassium stays outside cells — the opposite of chronic toxicity, where hypokalemia predisposes. <b>Hyperkalemia in digoxin poisoning, along with life-threatening arrhythmias or block, is an indication for digoxin immune Fab</b>, which binds digoxin one to one; it can itself precipitate heart failure (by removing the inotrope) or anaphylaxis. Potassium falls as digoxin is neutralized.<br><br><b>Educational objective:</b> Acute digoxin overdose causes hyperkalemia; hyperkalemia or dangerous arrhythmias are indications for digoxin immune Fab.",
wrong={0:"Calcium has traditionally been avoided in digoxin toxicity and is not the antidote; Fab is.",
2:"Giving potassium to a hyperkalemic patient is dangerous; potassium repletion applies to chronic toxicity with hypokalemia.",
3:"Quinidine raises digoxin levels and would worsen toxicity.",
4:"Binding resins lower potassium slowly and do not reverse digoxin's effects on the heart."},
eli5="A big digoxin overdose jams the sodium pumps everywhere, so potassium piles up in the blood. The antidote is antibody pieces that grab the digoxin and pull it out of action."),

dict(sec=10, img=None,
stem="A 62-year-old man is admitted with an inferior myocardial infarction. Two hours later he becomes light-headed and diaphoretic. His pulse is 38/min, and blood pressure is 82/48 mm Hg. The electrocardiogram shows sinus bradycardia with second-degree atrioventricular block, Mobitz I.{FIG}Which of the following is the most appropriate initial pharmacotherapy?",
choices=["Adenosine","Atropine","Digoxin","Epinephrine infusion","Metoprolol","Verapamil"], key=1,
exp="<b>Atropine is first-line for symptomatic bradycardia</b>, and Dr. Scully said this is the one indication-to-drug pairing he would ask: atropine first, then the catecholamines (epinephrine, dopamine), with pacing if needed. Atropine is a nonselective muscarinic antagonist that blocks vagal M2 input to the sinoatrial and atrioventricular nodes, raising the rate and speeding nodal conduction. Inferior infarcts often cause vagally mediated bradycardia and nodal (Mobitz I) block, which respond well. (At low doses atropine can briefly slow the heart before the expected tachycardia.)<br><br><b>Educational objective:</b> Atropine is the first-line drug for symptomatic bradycardia and atrioventricular nodal block; catecholamines are second line.",
wrong={0:"Adenosine causes transient block and would worsen bradycardia.",
2:"Digoxin increases vagal tone and slows the node further.",
3:"A catecholamine infusion such as epinephrine is the second-line option if atropine fails, not the first.",
4:"Metoprolol slows the rate and nodal conduction further and lowers blood pressure.",
5:"Verapamil slows the sinoatrial and atrioventricular nodes and is contraindicated here."},
eli5="His heart is too slow because the vagus nerve is slamming the brakes after a bottom-wall heart attack. Atropine blocks the vagus brake and speeds the heart back up."),

dict(sec=10, img=None,
stem="A 34-year-old man is brought to the emergency department after receiving repeated doses of atropine in the field. He is agitated, picking at the air and disoriented. His temperature is 39.4°C (103°F), pulse is 132/min, and his skin is hot, flushed and dry. The pupils are dilated and do not constrict to light, and bowel sounds are absent.{FIG}Which of the following is the most appropriate antidote?",
choices=["Atropine","Physostigmine","Pralidoxime","Pyridostigmine"], key=1,
exp="Mad as a hatter (delirium), dry as a bone, blind as a bat (mydriasis, cycloplegia), red as a beet, hot as a hare: the <b>anticholinergic toxidrome</b>. <b>Physostigmine</b> is an acetylcholinesterase inhibitor that lets acetylcholine build up and compete atropine off the receptors, and because it is a tertiary amine it <b>crosses the blood–brain barrier</b>, reversing the central delirium as well as the peripheral signs. Pyridostigmine (a quaternary amine) does not enter the central nervous system, and pralidoxime is for organophosphate (cholinergic) poisoning — the opposite problem.<br><br><b>Educational objective:</b> Anticholinergic toxicity (from atropine) is reversed with physostigmine, which crosses the blood–brain barrier.",
wrong={0:"More atropine would worsen the anticholinergic toxidrome.",
2:"Pralidoxime regenerates acetylcholinesterase after organophosphate poisoning, the opposite (cholinergic) problem.",
3:"Pyridostigmine is quaternary and does not cross the blood–brain barrier, so it would not reverse the delirium."},
eli5="Too much atropine blocks acetylcholine everywhere, including the brain. Physostigmine stops acetylcholine from being broken down, so it builds up and pushes the atropine off, and it reaches the brain too."),
]
